-- 2026-08-09 — lines_and_planes_in_space FIRST EYE WALK: 2 new rows + 2 updates.
-- Generated by src/scripts/_seed_engine_bug_queue_lines_and_planes_eye_walk.ts — idempotent.

INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('eye_motion_gate_read_the_cached_config_which_for_a_hand_seeded_concept_carries_no_states', 'D5 was fed cached.physics_config, which for every chemistry/mathematics concept contains only epic_l_path — so the motion gate silently never ran', 'CRITICAL', 'peter_parker:visual_validator', 'visual_eyes.ts computed expectsMotion = deriveMotionExpectations(cached.physics_config) while the sibling reveal and hold derivations two lines below read conceptJson ?? cached.physics_config. A SUBJECT-NAMESPACE concept (chemistry / mathematics) never runs the live generation pipeline — it registers at site #1 only, the isolation contract — so it is HAND-SEEDED into simulation_cache by _seed_subject_cache.ts, and the seeded physics_config carries ONLY epic_l_path: no field_3d_config, no states. resolveField3dStates() therefore returned null, deriveMotionExpectations returned an empty object, every state resolved to undefined, and pixelGate emitted D5 as PASSED with evidence "Skipped -- motion expectation unknown". visual_eyes aggregates skips into the headline count, so lines_and_planes_in_space first ever visual run reported "39 checks / 39 passed / 0 failed" with NINE skips inside it and zero motion coverage. THIS IS THE MECHANISM behind the #7 wave finding that adding a vg entry to deriveMotionExpectations did not make D5 run: the registration was correct and unreachable. Fixed by loading the concept JSON before the derivation and passing conceptJson ?? cached.physics_config, matching the established sibling convention. VERIFIED: the same concept re-run reports 38 passed / 1 FAILED with D5 executing on all 9 states, and the single failure is a genuine one.', 'EVERY derivation in a gate runner reads the SAME source, and that source is the concept JSON with the cache as fallback — never the cache alone. A hand-seeded cache row is a DIFFERENT SHAPE from a pipeline-generated one, so any gate reading it directly is correct for physics and silently inert for every other subject. When a gate is reported as not running, check WHAT IT IS FED before adding registrations to it: a registration cannot fire on a config that does not contain the key it registers against. Generally: a skip is not a pass, and a gate that skips 100 percent of states must be treated as a failed run, not a clean one.', 'js_eval', 'After any visual:eyes run, assert the count of D5 lines whose evidence contains "Skipped" is ZERO for any concept with a non-empty animate[] or declared motion; assert deriveMotionExpectations returns a non-empty map for one concept from EACH subject namespace (physics, chemistry, mathematics). Negative control: feed it a hand-seeded physics_config and assert it returns empty, proving the probe discriminates.', 'FIXED', ARRAY['lines_and_planes_in_space', 'vector_products_in_space']::text[], ARRAY['src/scripts/visual_eyes.ts']::text[], 'session_2026-08-09_lines_and_planes_eye_walk', 'incident'),
('vg_object_group_membership_authored_as_group_while_the_engine_reads_groups_so_the_selector_is_inert', 'The Δ10 scene_group selector does nothing, because objects declare "group" and vgInGroup reads "groups"', 'MAJOR', 'ambiguous', 'vgInGroup(o, group) tests o.groups (PLURAL, an array) and RETURNS TRUE for any object that does not declare it — an object with no groups is present in every group, which is the correct permissive default. The #9 concept JSON authors group (SINGULAR) on its lines, a key the engine never reads. Net effect: every object passes the membership test in every group, so selecting scene_group A or B changes nothing and all eight objects render simultaneously. That co-present scene is EXACTLY what Δ10 was specified to prevent: the explore camera solved over all eight objects and all six sliders returns a minimum pairwise screen separation of 1.35 degrees, which is why the state was split into two groups with their own poses (41.1 and 11.0 degrees). So the one measured design decision the explore state rests on is silently not in effect. Neither the schema nor the gate catches it, because an unknown key is legal under Zod passthrough and a permissive membership default cannot distinguish "no groups authored" from "groups authored under the wrong name".', 'A permissive default (absent membership means present everywhere) must not be reachable by a TYPO. Where a scenario ships a selector, the gate asserts the selector CHANGES the rendered object set between its declared options — a selector that resolves to the same scene for every option is a failed selector, not a passing one. Corollary for authoring: any key that governs visibility is verified by observing the picture change, never by its presence in the JSON. Add groups to the declared vg type so the singular form is a type error rather than silent data.', 'js_eval', 'For a state declaring scene_groups, resolve the scene once per group key and assert the resolved object id sets DIFFER; assert every authored object carries a groups array when more than one group is declared. Negative control: the shipped #9 STATE_9 must FAIL this probe today.', 'OPEN', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts']::text[], 'session_2026-08-09_lines_and_planes_eye_walk', 'incident')
